android.extraProguardRules:
# --- Autonomic R8 keeps (see plugins/withR8Memory.js for the heap bump) ---
# Only libraries WITHOUT consumer rules of their own need entries here.
# Shipping their own already: expo, expo-modules-core, expo-updates,
# react-native-reanimated, react-native-svg, react-native-health-connect,
# openiap-google (dev.hyo.openiap.models.**).

# Gson 2.10.1 (pulled in by openiap-google) ships no rules of its own and
# reflects over field names + generic signatures.
-keepattributes Signature
-keepattributes *Annotation*
-keep class com.google.gson.reflect.TypeToken { *; }
-keep class * extends com.google.gson.reflect.TypeToken
-keepclassmembers,allowobfuscation class * { @com.google.gson.annotations.SerializedName <fields>; }

# react-native-android-widget: the AppWidgetProvider subclasses are reached
# only from AndroidManifest.xml and the headless task registry (index.js).
-keep class com.reactnativeandroidwidget.** { *; }

# JSI/TurboModule installers are called from C++, so nothing in Java
# references them and R8 would happily strip them.
-keep class com.mrousavy.mmkv.** { *; }
-keep class com.mrousavy.camera.** { *; }
-keep class com.worklets.** { *; }
-keep class com.bleplx.** { *; }

# expo-notifications has no consumer rules; its receivers/services are
# manifest-referenced but the serialized trigger/content classes are not.
-keep class expo.modules.notifications.** { *; }
-keep class expo.modules.iap.** { *; }
